    edges {
      node {
        id
        number
        active
        barcode
        quantity {
          value
          unitId
        }
        inventoryStatusId
        inventoryTypeId
        locationId
        lotId
        masterInventoryId
        externalId
        productStrategyProcessId
        productStrategyProcess {
          id
          productStrategy {
            product { id externalId name }
          }
        }
        destinationTransactions(
          where: {
            destinationInventoryStatusId: {
              _eq: "Count"
            }
          },
          first:1,
          orderBy: {field:createdAt, direction:desc}
        ){
          edges {
            node {
              sourceInventoryStatusId
            }
          }
        }
      }
    }
  }
  detail:inventoryCountDetail(where:$whereD) {
    edges {
      node {
        id
        ejected
        approved
        complete
        expectedLocationId
        expectedQuantity {value unitId}
        count {
          id
          statusId
          progress
        }
      }
    }
  }

}

